function toggleFormulaDrawer(forceState) {
  isFormulaDrawerOpen = typeof forceState === "boolean" ? forceState : !isFormulaDrawerOpen;
  const drawer = document.getElementById("formulaDrawerLeft");
  const btn = document.getElementById("btnFormulaDrawerToggle");
  const img = document.getElementById("capyFormulaToggleImg");

  if (drawer) drawer.classList.toggle("open", isFormulaDrawerOpen);
  if (btn) btn.classList.toggle("open", isFormulaDrawerOpen);
  document.body.classList.toggle("formula-open", isFormulaDrawerOpen);
  if (img) {
    img.src = isFormulaDrawerOpen ? "assets/capy_labcoat.webp" : "assets/capy_banana.webp";
  }
}

function renderFormulaSheet(unitKey) {
  ["u6", "u7", "u8"].forEach(k => {
    const b = document.getElementById("fTab_" + k);
    if (b) {
      b.className = k === unitKey
        ? "px-3.5 py-1 rounded-full text-sm font-bold bg-amber-400 text-slate-950 font-patrick"
        : "px-3.5 py-1 rounded-full text-sm font-bold bg-slate-800 text-slate-200 hover:bg-slate-700 font-patrick";
    }
  });

  const container = document.getElementById("formulaDrawerContent");
  if (!container) return;
  const list = FORMULA_SHEET_DATA[unitKey] || FORMULA_SHEET_DATA.u6;

  container.innerHTML = list.map(item => `
    <div class="math-showcase-box !my-0 !p-3.5 space-y-1.5">
      <div class="text-base font-bold text-amber-300 font-patrick">${item.name}</div>
      ${item.exprHtml}
      <div class="border-t border-slate-700/60 pt-1.5">${item.despejesHtml}</div>
      <div class="text-xs text-slate-200 pt-1 font-sans leading-relaxed">${item.vars}</div>
    </div>
  `).join("");
}

// ============================================================================
// 2B. NUEVA BARRA LATERAL DERECHA: 'CALCULADORA' DE DATO FALTANTE (CON CAPIBARA NUEVO)
// ============================================================================
function toggleCalculatorDrawer(forceState) {
  isCalculatorDrawerOpen = typeof forceState === "boolean" ? forceState : !isCalculatorDrawerOpen;
  const drawer = document.getElementById("calculatorDrawerRight");
  const btn = document.getElementById("btnCalculatorDrawerToggle");
  const hintBtn = document.getElementById("btnCalculatorHint");
  const img = document.getElementById("capyCalculatorToggleImg");

  if (drawer) drawer.classList.toggle("open", isCalculatorDrawerOpen);
  if (btn) btn.classList.toggle("open", isCalculatorDrawerOpen);
  if (hintBtn) hintBtn.classList.toggle("active", isCalculatorDrawerOpen);
  document.body.classList.toggle("calc-open", isCalculatorDrawerOpen);
  if (img) {
    img.src = isCalculatorDrawerOpen ? "assets/capy_calc_open.webp" : "assets/capy_calc.webp";
  }
}

