// ============================================================================
// 9. ESTADO Y NAVEGACIÓN DE VIDEOS, CONCEPTOS, EJERCICIOS Y MODO DIVIDIDO 50/50
// ============================================================================
let currentUnit = "u6";
let activeVideoObj = null;
let currentConceptId = "c1";
let currentBottomMode = "guided";
let currentExerciseId = "ex1";
let currentSimId = "sim1";
let unlockedResolutions = {};
let savedVideoTimes = {};
let ytPlayer = null;
let ytTimerInterval = null;

function loadSavedTimes() {
  try {
    const raw = localStorage.getItem("fq_unaj_video_times_v4");
    if (raw) savedVideoTimes = JSON.parse(raw) || {};
  } catch (e) {
    savedVideoTimes = {};
  }
}

function saveVideoTime(videoId, sec) {
  const cleanSec = Math.max(0, Math.floor(Number(sec) || 0));
  savedVideoTimes[videoId] = cleanSec;
  try {
    localStorage.setItem("fq_unaj_video_times_v4", JSON.stringify(savedVideoTimes));
  } catch (e) {}
  updateVideoBarsProgressUI();
}

function formatMMSS(sec) {
  const s = Math.max(0, Math.floor(Number(sec) || 0));
  const m = Math.floor(s / 60);
  const r = s % 60;
  return String(m).padStart(2, "0") + ":" + String(r).padStart(2, "0");
}

function getAllVideosForUnit(uKey) {
  const rows = UNIT_VIDEOS_ROWS[uKey] || UNIT_VIDEOS_ROWS.u6;
  return [...(rows.row1 || []), ...(rows.row2 || [])];
}

function findUnitAndVideoById(videoId) {
  for (const uKey of ["u6", "u7", "u8"]) {
    const list = getAllVideosForUnit(uKey);
    const found = list.find(v => v.id === videoId);
    if (found) return { unitKey: uKey, video: found };
  }
  return null;
}

function startFallbackProgressTimer() {
  if (ytTimerInterval) clearInterval(ytTimerInterval);
  ytTimerInterval = setInterval(() => {
    if (!activeVideoObj || activeVideoObj.playlistId) return;
    if (ytPlayer && typeof ytPlayer.getCurrentTime === "function" && typeof ytPlayer.getPlayerState === "function") {
      try {
        if (ytPlayer.getPlayerState() === 1) {
          const cur = Math.floor(ytPlayer.getCurrentTime() || 0);
          saveVideoTime(activeVideoObj.id, cur);
        }
      } catch (e) {}
    }
  }, 2000);
}

window.onYouTubeIframeAPIReady = function () {
  initOrUpdateYouTubeEmbed(null);
};

function initOrUpdateYouTubeEmbed(overrideStartSec) {
  const allVids = getAllVideosForUnit(currentUnit);
  if (!activeVideoObj) activeVideoObj = allVids[0];
  const v = activeVideoObj;
  if (!v) return;

  const iframe = document.getElementById("unitVideoIframe");
  if (!iframe) return;

  const startSec = overrideStartSec !== null && overrideStartSec !== undefined
    ? overrideStartSec
    : (savedVideoTimes[v.id] || 0);

  if (overrideStartSec !== null && overrideStartSec !== undefined) {
    saveVideoTime(v.id, overrideStartSec);
  }

  const startQuery = startSec > 0 ? `&start=${startSec}&autoplay=1` : "";
  iframe.src = `https://www.youtube-nocookie.com/embed/${v.ytId}?enablejsapi=1&rel=0${startQuery}`;
}

function selectVideoById(videoId, customStartSec = null) {
  const match = findUnitAndVideoById(videoId);
  if (match && match.unitKey !== currentUnit) {
    currentUnit = match.unitKey;
    ["navBtnU6", "navBtnU7", "navBtnU8", "navBtnEj", "navBtnParcial"].forEach(id => {
      const el = document.getElementById(id);
      if (el) el.classList.remove("active");
    });
    const activeBtn = document.getElementById("navBtn" + currentUnit.toUpperCase());
    if (activeBtn) activeBtn.classList.add("active");
    renderConceptPillsAndDevelopment();
    renderFormulaSheet(currentUnit);
    renderCalculatorSheet(currentUnit);
  }

  const allVids = getAllVideosForUnit(currentUnit);
  const found = (match && match.video) || allVids.find(v => v.id === videoId) || allVids[0];
  if (!found) return;

  activeVideoObj = found;
  renderVideoBars();
  renderVideoConceptsBox();
  initOrUpdateYouTubeEmbed(customStartSec);

  // Si la vista dividida de archivo está abierta, sincronizamos automáticamente el PDF a la página donde habla de este video
  if (currentOpenFileKey && (currentOpenFileKey === "u6" || currentOpenFileKey === "u7" || currentOpenFileKey === "u8")) {
    const targetPage = (found.pdfPages && found.pdfPages[0]) ? found.pdfPages[0] : 1;
    if (currentOpenFileKey !== currentUnit) {
      openOriginalFileViewer(currentUnit, targetPage);
    } else {
      scrollToOriginalPage(targetPage);
    }
  }
}

// Al apretar 'Ver en Video', lleva al instante del video, divide la pantalla 50/50 con el PDF abierto a la derecha en la página exacta, y a la izquierda el video con su ventana de info debajo (imagen b35f94)
function jumpToVideoConcept(videoId, sec, pdfFileKey = null, pdfPageNum = null) {
  selectVideoById(videoId, sec);
  const targetFile = pdfFileKey || currentUnit;
  const targetPage = pdfPageNum || (activeVideoObj && activeVideoObj.pdfPages && activeVideoObj.pdfPages[0]) || 1;
  openOriginalFileViewer(targetFile, targetPage);
  const topEl = document.getElementById("topVideoSection");
  if (topEl) topEl.scrollIntoView({ behavior: "smooth", block: "start" });
}

function adjustSavedTimeManual(deltaSec) {
  if (!activeVideoObj) return;
  const cur = savedVideoTimes[activeVideoObj.id] || 0;
  const next = Math.max(0, Math.min(activeVideoObj.durationSec, cur + deltaSec));
  saveVideoTime(activeVideoObj.id, next);
  selectVideoById(activeVideoObj.id, next);
}

function renderSingleBarRowHtml(list, rowClass, rowLabel) {
  if (!list || list.length === 0) return "";
  return `
    <div class="video-bars-row-wrap">
      ${rowLabel ? `<div class="video-bars-row-label">${rowLabel}</div>` : ""}
      <div class="video-bars-row">
        ${list.map(v => {
          const savedSec = savedVideoTimes[v.id] || 0;
          const pct = Math.min(100, Math.round((savedSec / (v.durationSec || 400)) * 100));
          const isActive = activeVideoObj && activeVideoObj.id === v.id;
          const tooltip = `${v.shortLabel} (${v.durationFmt}) — Guardado en ${formatMMSS(savedSec)}`;
          return `
            <button
              type="button"
              onclick="selectVideoById('${v.id}')"
              class="video-bar-pill ${rowClass} ${isActive ? 'active' : ''}"
              title="${tooltip}"
              aria-label="${tooltip}">
              <span id="barProg_${v.id}" class="video-bar-progress" style="width: ${pct}%;"></span>
              <span class="video-bar-code">${v.code || ""}</span>
            </button>
          `;
        }).join("")}
      </div>
    </div>
  `;
}

function renderVideoBars() {
  const barsContainer = document.getElementById("videoBarsContainer");
  if (!barsContainer) return;
  const rows = UNIT_VIDEOS_ROWS[currentUnit] || UNIT_VIDEOS_ROWS.u6;

  barsContainer.innerHTML =
    renderSingleBarRowHtml(rows.row1, "row-playlist", rows.row1Label) +
    renderSingleBarRowHtml(rows.row2, "row-alvaro", rows.row2Label);
}

function updateVideoBarsProgressUI() {
  const allVids = getAllVideosForUnit(currentUnit);
  allVids.forEach(v => {
    const el = document.getElementById("barProg_" + v.id);
    if (el) {
      const savedSec = savedVideoTimes[v.id] || 0;
      const pct = Math.min(100, Math.round((savedSec / (v.durationSec || 400)) * 100));
      el.style.width = pct + "%";
    }
  });
  const savedBadge = document.getElementById("currentVideoSavedReadout");
  if (savedBadge && activeVideoObj) {
    savedBadge.textContent = formatMMSS(savedVideoTimes[activeVideoObj.id] || 0) + " / " + activeVideoObj.durationFmt;
  }
}

function renderVideoConceptsBox() {
  const allVids = getAllVideosForUnit(currentUnit);
  if (!activeVideoObj) activeVideoObj = allVids[0];
  const v = activeVideoObj;
  if (!v) return;

  const titleEl = document.getElementById("videoBoxTitle");
  const contentEl = document.getElementById("videoBoxConceptsContent");
  if (!titleEl || !contentEl) return;

  const savedSec = savedVideoTimes[v.id] || 0;

  titleEl.innerHTML = `
    <div class="flex flex-col items-center justify-center gap-1 text-center">
      <span class="text-sm uppercase tracking-wider text-amber-300 font-patrick">
        ${v.rowType === "alvaro" ? "Clase del Prof. Álvaro Sánchez Jovic" : `Video Oficial ${v.code || ""}`}
        • Guardado en: <span id="currentVideoSavedReadout" class="text-cyan-300 font-bold">${formatMMSS(savedSec)} / ${v.durationFmt}</span>
      </span>
      <h2 class="text-xl md:text-2xl font-bold text-white font-patrick">${v.title}</h2>
    </div>
  `;

  contentEl.innerHTML = `
    <div class="flex flex-col items-center justify-center gap-4 pb-3">
      <div class="flex items-center justify-center gap-4 my-1 flex-wrap">
        <img src="${v.capyImg}" alt="Capibara" class="w-16 h-16 object-contain sprite-no-bg anim-capy">
        <div class="flex flex-wrap items-center justify-center gap-2">
          <button type="button" onclick="adjustSavedTimeManual(-30)" class="px-3.5 py-1 text-sm rounded-full bg-slate-800/90 hover:bg-slate-700 text-cyan-200 font-patrick">⏪ -30s</button>
          <button type="button" onclick="adjustSavedTimeManual(30)" class="px-3.5 py-1 text-sm rounded-full bg-slate-800/90 hover:bg-slate-700 text-cyan-200 font-patrick">+30s ⏩</button>
          <button type="button" onclick="saveVideoTime('${v.id}', 0); selectVideoById('${v.id}', 0)" class="px-3.5 py-1 text-sm rounded-full bg-slate-800/90 hover:bg-amber-500 text-amber-200 hover:text-slate-950 font-patrick">↺ 00:00</button>
        </div>
        <img src="${v.sciIcon}" alt="Ciencia" class="w-14 h-14 object-contain sprite-no-bg anim-sci-icon">
      </div>

      <div class="w-full space-y-4">
        ${v.keyConcepts.map(kc => `
          <div class="p-4 rounded-2xl bg-slate-950/55 border border-slate-800/80 space-y-2.5">
            <div class="text-amber-300 font-bold text-lg md:text-xl font-patrick text-center">${kc.subtitle}</div>
            <p class="prose-justify-sm !mb-1">${kc.text}</p>
            <div class="math-showcase-box !my-2 !py-2.5 !px-3">
              ${kc.formulaHtml}
            </div>
            <div class="pt-1 flex flex-wrap items-center justify-center gap-2.5">
              <button type="button" onclick="selectVideoById('${v.id}', ${kc.sec})" class="px-4 py-1 text-sm font-bold rounded-full bg-amber-500/90 hover:bg-amber-400 text-slate-950 font-patrick transition">
                ▶ Reproducir Min ${formatMMSS(kc.sec)}
              </button>
              <button type="button" onclick="openOriginalFileViewer('${currentUnit}', ${v.pdfPages[0] || 1})" class="px-4 py-1 text-sm font-bold rounded-full bg-cyan-500/25 hover:bg-cyan-500/45 text-cyan-200 font-patrick transition">
                📄 Abrir PDF a la Derecha (Págs. ${v.pdfPages.join(', ')})
              </button>
            </div>
          </div>
        `).join("")}
      </div>
    </div>
  `;
}

// ============================================================================
// 10. CAJA CENTRAL: BARRA DE CONCEPTOS + DESARROLLO TEÓRICO
// ============================================================================
function getCurrentUnitConcepts() {
  if (currentUnit === "u6") return UNIDAD_6_CONCEPTS;
  return OTHER_UNITS_CONCEPTS[currentUnit] || UNIDAD_6_CONCEPTS;
}

function selectConceptPill(conceptId) {
  currentConceptId = conceptId;
  renderConceptPillsAndDevelopment();
}

function renderConceptPillsAndDevelopment() {
  const pillsBar = document.getElementById("dynamicConceptPillsBar");
  const devContainer = document.getElementById("unitDevelopmentContainer");
  if (!pillsBar || !devContainer) return;

  const concepts = getCurrentUnitConcepts();
  if (!concepts.some(c => c.id === currentConceptId)) {
    currentConceptId = concepts[0].id;
  }

  pillsBar.innerHTML = concepts.map(c => `
    <button type="button" onclick="selectConceptPill('${c.id}')" class="concept-btn ${currentConceptId === c.id ? 'active' : ''}">
      ${c.shortBtn}
    </button>
  `).join("");

  const activeConcept = concepts.find(c => c.id === currentConceptId) || concepts[0];

  devContainer.innerHTML = `
    <article class="p-4 md:p-7 rounded-3xl bg-slate-950/35 space-y-6">
      <div class="flex flex-col md:flex-row items-center justify-center gap-5 pb-2">
        <img src="${activeConcept.capyImg}" alt="Capibara" class="w-20 h-20 object-contain sprite-no-bg anim-capy">
        <div class="max-w-2xl text-center">
          <h3 class="text-2xl md:text-3xl font-bold text-amber-300 font-patrick">${activeConcept.title}</h3>
        </div>
        <img src="${activeConcept.sciIcon}" alt="Ícono Ciencia" class="w-16 h-16 object-contain sprite-no-bg anim-sci-icon">
      </div>

      <div class="space-y-5">
        ${activeConcept.theoryHtml}
      </div>

      <div class="pt-4 text-center">
        <div class="pdf-ref-footer">
          <img src="assets/lab_circle.webp" alt="Laboratorio" class="w-8 h-8 object-contain sprite-no-bg">
          <span class="text-base text-cyan-200 font-patrick">
            📚 <strong>Para profundizar en el PDF:</strong> Este tema se encuentra en <strong>${activeConcept.pdfPages}</strong>
          </span>
          <button type="button" onclick="openOriginalFileViewer('${currentUnit}', ${activeConcept.pdfPageNum})" class="px-4 py-1.5 text-sm font-bold rounded-full bg-amber-400 hover:bg-amber-300 text-slate-950 font-patrick transition">
            📄 Abrir PDF en Vista Dividida (Pág. ${activeConcept.pdfPageNum})
          </button>
          <button type="button" onclick="jumpToVideoConcept('${activeConcept.videoRefId}', ${activeConcept.videoRefSec}, '${currentUnit}', ${activeConcept.pdfPageNum})" class="px-4 py-1.5 text-sm font-bold rounded-full bg-cyan-400/30 hover:bg-cyan-400/50 text-cyan-100 font-patrick transition">
            🎥 Ver en Video + PDF (Vista 50/50)
          </button>
        </div>
      </div>
    </article>
  `;

  initActiveTheorySimulators();
}

// ============================================================================
// 11. CAJAS INFERIORES: 30 EJERCICIOS + 8 PROBLEMAS DE MODELO DE PARCIAL
// ============================================================================
function setBottomMode(mode) {
  currentBottomMode = mode;
  renderBottomBoxes();
}

function setExerciseUnitFilter(uFilter) {
  currentExerciseUnitFilter = uFilter;
  const filtered = getFilteredGuidedExercises();
  if (filtered.length > 0 && !filtered.some(e => e.id === currentExerciseId)) {
    currentExerciseId = filtered[0].id;
  }
  renderBottomBoxes();
}

function getFilteredGuidedExercises() {
  if (currentExerciseUnitFilter === "all") return GUIDED_EXERCISES;
  return GUIDED_EXERCISES.filter(e => e.unit === currentExerciseUnitFilter);
}

function selectGuidedExercise(exId) {
  currentExerciseId = exId;
  renderBottomBoxes();
}

function selectSimProblem(simId) {
  currentSimId = simId;
  renderBottomBoxes();
}

function confirmGuidedAttempt(exId) {
  const inputEl = document.getElementById("attemptInput_" + exId);
  const userText = inputEl ? inputEl.value.trim() : "";
  unlockedResolutions[exId] = {
    unlocked: true,
    userAttempt: userText || "Planteo verificado paso a paso."
  };
  renderBottomBoxes();
}

function evaluateSimulacro(simId) {
  const sim = EXAM_SIM_PROBLEMS.find(s => s.id === simId);
  if (!sim) return;

  const procEl = document.getElementById("simProc_" + simId);
  const procText = procEl ? procEl.value.trim() : "";

  let feedbackTitle = "";
  let feedbackBody = "";
  let isCorrect = false;

  if (sim.options) {
    const sel = document.querySelector(`input[name="simOpt_${simId}"]:checked`);
    const chosen = sel ? sel.value : "";
    if (!chosen) {
      feedbackTitle = "⚠️ Selecciona primero una de las opciones (A, B o C)";
      feedbackBody = "Elige una opción y escribe tu justificación física para evaluar tanto el procedimiento como el resultado.";
      unlockedResolutions[simId] = { unlocked: false, feedbackTitle, feedbackBody, isCorrect: false };
      renderBottomBoxes();
      return;
    }
    isCorrect = (chosen === sim.correctOption);
    feedbackTitle = isCorrect
      ? "✅ ¡Respuesta y razonamiento correctos! (Opción " + chosen + ")"
      : "❌ Elegiste la opción " + chosen + ", pero la correcta es la " + sim.correctOption;
    feedbackBody = procText
      ? `Tu justificación registrada: «${procText}». Revisa debajo la resolución completa.`
      : "Recuerda en el examen redactar siempre la justificación completa.";
  } else {
    const numEl = document.getElementById("simNum_" + simId);
    const rawVal = numEl ? numEl.value.trim().replace(",", ".") : "";
    const parsed = parseFloat(rawVal);
    if (isNaN(parsed)) {
      feedbackTitle = "⚠️ Ingresa un valor numérico en la casilla de respuesta";
      feedbackBody = "Escribe tu resultado numérico y las ecuaciones que planteaste para evaluar tu resolución.";
      unlockedResolutions[simId] = { unlocked: false, feedbackTitle, feedbackBody, isCorrect: false };
      renderBottomBoxes();
      return;
    }
    const relErr = Math.abs(parsed - sim.numericTarget) / sim.numericTarget;
    isCorrect = relErr <= sim.toleranceRel;
    if (isCorrect) {
      feedbackTitle = `✅ ¡Cálculo Exacto! Tu valor (${parsed} ${sim.unitTarget}) es correcto`;
      feedbackBody = "Revisa a la derecha el desarrollo completo con despeje algebraico y análisis dimensional.";
    } else {
      feedbackTitle = `🔍 Ingresaste ${parsed}, y el valor esperado es ${sim.numericTarget} ${sim.unitTarget}`;
      feedbackBody = "Revisa en la caja derecha la conversión de unidades al Sistema Internacional y el despeje paso a paso.";
    }
  }

  unlockedResolutions[simId] = {
    unlocked: true,
    feedbackTitle,
    feedbackBody,
    isCorrect
  };
  renderBottomBoxes();
}

